import 'dart:math';

import '../models/math_models.dart';

/// Deterministic, validated K-5 question generation.
///
/// The engine never trusts the client for correctness: production matches are
/// snapshotted from a server-side bank that is generated by this same code and
/// committed as a migration. The generator is deliberately independent of
/// Flutter so it can be unit tested and used by tooling.
class QuestionEngine {
  QuestionEngine._();

  static const int bankVersion = 1;

  static const List<String> _names = [
    'Ava',
    'Ben',
    'Mia',
    'Noah',
    'Zoe',
    'Leo',
    'Aria',
    'Sam',
    'Kai',
    'Luna',
    'Ira',
    'Max',
  ];

  static const List<({String singular, String plural, String emoji})> _items = [
    (singular: 'apple', plural: 'apples', emoji: '🍎'),
    (singular: 'star', plural: 'stars', emoji: '⭐'),
    (singular: 'cookie', plural: 'cookies', emoji: '🍪'),
    (singular: 'pencil', plural: 'pencils', emoji: '✏️'),
    (singular: 'marble', plural: 'marbles', emoji: '🔵'),
    (singular: 'sticker', plural: 'stickers', emoji: '🌈'),
    (singular: 'block', plural: 'blocks', emoji: '🧱'),
    (singular: 'orange', plural: 'oranges', emoji: '🍊'),
  ];

  static MathQuestion generate({
    required int grade,
    required MathTopic topic,
    required MathDifficulty difficulty,
    required int seed,
  }) {
    if (grade < 0 || grade > 5) {
      throw ArgumentError.value(
        grade,
        'grade',
        'Grade must be between K and 5',
      );
    }
    if (difficulty == MathDifficulty.adaptive) {
      throw ArgumentError.value(
        difficulty,
        'difficulty',
        'Generate a concrete difficulty; adaptive is chosen by the server',
      );
    }

    final random = Random(seed);
    final question = switch (topic) {
      MathTopic.addition => _addition(grade, difficulty, random),
      MathTopic.subtraction => _subtraction(grade, difficulty, random),
      MathTopic.multiplication => _multiplication(grade, difficulty, random),
      MathTopic.division => _division(grade, difficulty, random),
      MathTopic.fractions => _fraction(grade, difficulty, random),
      MathTopic.geometry => _geometry(grade, difficulty, random),
      MathTopic.measurement => _measurement(grade, difficulty, random),
      MathTopic.placeValue => _placeValue(grade, difficulty, random),
      MathTopic.mixed => _mixed(grade, difficulty, random),
    };
    _validate(question);
    return question;
  }

  /// Generates a de-duplicated batch used to seed the server question bank.
  static List<MathQuestion> generateBatch({
    required int count,
    required int seedOffset,
  }) {
    final questions = <MathQuestion>[];
    final seen = <String>{};

    for (var grade = 0; grade <= 5; grade++) {
      for (final topic in MathTopic.values) {
        for (final difficulty in [
          MathDifficulty.easy,
          MathDifficulty.medium,
          MathDifficulty.hard,
        ]) {
          var attempts = 0;
          var generated = 0;
          while (generated < count && attempts < count * 25) {
            final seed =
                seedOffset +
                grade * 100000 +
                topic.index * 10000 +
                difficulty.index * 1000 +
                attempts;
            attempts++;
            final question = generate(
              grade: grade,
              topic: topic,
              difficulty: difficulty,
              seed: seed,
            );
            final key =
                '$grade|${topic.dbValue}|${difficulty.dbValue}|${question.text}|${question.correctAnswer}';
            if (seen.add(key)) {
              questions.add(question);
              generated++;
            }
          }
          if (generated < count) {
            throw StateError(
              'Only generated $generated/$count unique questions for '
              'grade $grade, ${topic.dbValue}, ${difficulty.dbValue}',
            );
          }
        }
      }
    }
    return questions;
  }

  // ---------------------------------------------------------------------------
  // Addition
  // ---------------------------------------------------------------------------

  static MathQuestion _addition(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    final (a, b) = _additionPair(grade, difficulty, r);
    final sum = a + b;
    final item = _items[r.nextInt(_items.length)];
    final asWordProblem = grade >= 1 && r.nextBool();
    final name = _names[r.nextInt(_names.length)];

    final text = asWordProblem
        ? '$name has $a ${item.plural}. They get $b more. '
              'How many ${item.plural} does $name have now?'
        : '$a + $b = ?';

    final visual = !asWordProblem && grade <= 1 && sum <= 20
        ? QuestionVisual(
            type: 'objects',
            data: {
              'emoji': item.emoji,
              'groups': [a, b],
              'operator': '+',
            },
          )
        : null;

    final explanation = asWordProblem
        ? 'Start with $a and add $b more. $a + $b = $sum, '
              'so $name has $sum ${item.plural}.'
        : _additionExplanation(a, b, sum);

    return _q(
      grade: grade,
      topic: MathTopic.addition,
      difficulty: difficulty,
      skill: switch (grade) {
        0 => 'add_within_10',
        1 => 'add_within_20',
        2 => 'add_within_100',
        3 => 'add_three_digit',
        4 => 'add_multi_digit',
        _ => 'add_large_numbers',
      },
      text: text,
      correct: '$sum',
      options: _integerOptions(sum, r, maxValue: max(sum + 10, 20)),
      explanation: explanation,
      visual: visual,
      estimatedSeconds: grade <= 1 ? 10 : 15,
    );
  }

  static (int, int) _additionPair(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    final level = grade * 3 + difficulty.index;
    switch (level) {
      case 0:
        return (_between(r, 0, 4), _between(r, 0, 5));
      case 1:
        return (_between(r, 0, 8), _between(r, 0, 5));
      case 2:
        return (_between(r, 1, 9), _between(r, 1, 9));
      case 3:
        return (_between(r, 0, 10), _between(r, 0, 9));
      case 4:
        return (_between(r, 2, 15), _between(r, 2, 9));
      case 5:
        return (_between(r, 5, 18), _between(r, 2, 12));
      case 6:
        return (_between(r, 5, 30), _between(r, 5, 20));
      case 7:
        return (_between(r, 10, 60), _between(r, 10, 40));
      case 8:
        return (_between(r, 20, 120), _between(r, 20, 90));
      case 9:
        return (_between(r, 20, 900), _between(r, 20, 99));
      case 10:
        return (_between(r, 100, 900), _between(r, 100, 800));
      case 11:
        return (_between(r, 500, 999), _between(r, 100, 899));
      case 12:
        return (_between(r, 1000, 9000), _between(r, 100, 900));
      case 13:
        return (_between(r, 1000, 8000), _between(r, 1000, 8000));
      case 14:
        return (_between(r, 5000, 40000), _between(r, 1000, 9000));
      case 15:
        return (_between(r, 10000, 90000), _between(r, 1000, 9000));
      case 16:
        return (_between(r, 10000, 90000), _between(r, 10000, 80000));
      default:
        return (_between(r, 1000, 9000), _between(r, 1000, 9000));
    }
  }

  // ---------------------------------------------------------------------------
  // Subtraction
  // ---------------------------------------------------------------------------

  static MathQuestion _subtraction(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    final (a, b) = _subtractionPair(grade, difficulty, r);
    final difference = a - b;
    final item = _items[r.nextInt(_items.length)];
    final asWordProblem = grade >= 1 && r.nextBool();
    final name = _names[r.nextInt(_names.length)];

    final text = asWordProblem
        ? '$name had $a ${item.plural} and gave away $b. '
              'How many ${item.plural} are left?'
        : '$a − $b = ?';

    final explanation = asWordProblem
        ? 'Take $b away from $a. $a − $b = $difference, '
              'so $difference ${item.plural} are left.'
        : _subtractionExplanation(a, b, difference);

    return _q(
      grade: grade,
      topic: MathTopic.subtraction,
      difficulty: difficulty,
      skill: switch (grade) {
        0 => 'subtract_within_10',
        1 => 'subtract_within_20',
        2 => 'subtract_within_100',
        3 => 'subtract_three_digit',
        4 => 'subtract_multi_digit',
        _ => 'subtract_large_numbers',
      },
      text: text,
      correct: '$difference',
      options: _integerOptions(difference, r, maxValue: max(a, 20)),
      explanation: explanation,
      visual: !asWordProblem && grade == 0
          ? QuestionVisual(
              type: 'number_line',
              data: {'min': 0, 'max': max(a, 10), 'start': a, 'jump': -b},
            )
          : null,
      estimatedSeconds: grade <= 1 ? 12 : 16,
    );
  }

  static (int, int) _subtractionPair(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    final level = grade * 3 + difficulty.index;
    switch (level) {
      case 0:
        final a = _between(r, 2, 10);
        return (a, _between(r, 0, a));
      case 1:
        final a = _between(r, 5, 10);
        return (a, _between(r, 1, a));
      case 2:
        final a = _between(r, 8, 15);
        return (a, _between(r, 1, a - 1));
      case 3:
        final a = _between(r, 10, 20);
        return (a, _between(r, 1, 10));
      case 4:
        final a = _between(r, 15, 20);
        return (a, _between(r, 2, 12));
      case 5:
        final a = _between(r, 20, 30);
        return (a, _between(r, 2, 18));
      case 6:
        final a = _between(r, 20, 60);
        return (a, _between(r, 5, 20));
      case 7:
        final a = _between(r, 40, 100);
        return (a, _between(r, 10, 40));
      case 8:
        final a = _between(r, 80, 200);
        return (a, _between(r, 10, 80));
      case 9:
        final a = _between(r, 200, 900);
        return (a, _between(r, 20, 150));
      case 10:
        final a = _between(r, 300, 900);
        return (a, _between(r, 100, 299));
      case 11:
        final a = _between(r, 500, 999);
        return (a, _between(r, 100, 400));
      case 12:
        final a = _between(r, 1000, 9000);
        return (a, _between(r, 100, 800));
      case 13:
        final a = _between(r, 2000, 9000);
        return (a, _between(r, 1000, 7000));
      case 14:
        final a = _between(r, 10000, 90000);
        return (a, _between(r, 1000, 8000));
      case 15:
        final a = _between(r, 10000, 90000);
        return (a, _between(r, 10000, 80000));
      case 16:
        final a = _between(r, 20000, 90000);
        return (a, _between(r, 5000, 15000));
      default:
        final a = _between(r, 1000, 9000);
        return (a, _between(r, 100, 900));
    }
  }

  // ---------------------------------------------------------------------------
  // Multiplication
  // ---------------------------------------------------------------------------

  static MathQuestion _multiplication(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    final (a, b) = _multiplicationPair(grade, difficulty, r);
    final product = a * b;
    final asWordProblem = grade >= 2 && r.nextBool();
    final item = _items[r.nextInt(_items.length)];
    final name = _names[r.nextInt(_names.length)];
    final groups = _between(r, 2, 6);

    final text = asWordProblem
        ? '$name has $a boxes with $b ${item.plural} in each box. '
              'How many ${item.plural} are there in all?'
        : '$a × $b = ?';

    final explanation = asWordProblem
        ? '$a groups of $b make ${a * b}. '
              'You can also add $b ${a == 1 ? 'time' : 'times'}: '
              '${List.filled(a, '$b').join(' + ')} = $product.'
        : _multiplicationExplanation(a, b, product);

    final visual = !asWordProblem && a <= 6 && b <= 6
        ? QuestionVisual(
            type: 'array',
            data: {'rows': a, 'cols': b, 'emoji': item.emoji},
          )
        : grade <= 2 && !asWordProblem
        ? QuestionVisual(
            type: 'objects',
            data: {
              'emoji': item.emoji,
              'groups': List.filled(groups, b),
              'operator': '×',
              'groupsCount': a,
            },
          )
        : null;

    return _q(
      grade: grade,
      topic: MathTopic.multiplication,
      difficulty: difficulty,
      skill: switch (grade) {
        0 => 'equal_groups',
        1 => 'times_tables_2_5_10',
        2 => 'times_tables_intro',
        3 => 'times_tables',
        4 => 'multiply_two_by_one',
        _ => 'multiply_two_by_two',
      },
      text: text,
      correct: '$product',
      options: _integerOptions(product, r, maxValue: max(product + 12, 24)),
      explanation: explanation,
      visual: visual,
      estimatedSeconds: grade <= 2 ? 12 : 16,
    );
  }

  static (int, int) _multiplicationPair(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    switch (grade) {
      case 0:
        return (_between(r, 1, 3), _between(r, 2, 5));
      case 1:
        final table = [2, 5, 10][r.nextInt(3)];
        return (
          table,
          _between(r, 1, difficulty == MathDifficulty.easy ? 5 : 10),
        );
      case 2:
        final table = [2, 3, 4, 5, 10][r.nextInt(5)];
        return (
          table,
          _between(r, 1, difficulty == MathDifficulty.hard ? 12 : 8),
        );
      case 3:
        return (
          _between(r, 2, difficulty == MathDifficulty.easy ? 5 : 10),
          _between(r, 2, difficulty == MathDifficulty.easy ? 5 : 10),
        );
      case 4:
        final a = difficulty == MathDifficulty.easy
            ? _between(r, 10, 20)
            : _between(r, 20, 60);
        return (a, _between(r, 2, difficulty == MathDifficulty.hard ? 9 : 5));
      default:
        final a = difficulty == MathDifficulty.easy
            ? _between(r, 11, 20)
            : _between(r, 20, 50);
        return (
          a,
          difficulty == MathDifficulty.easy
              ? _between(r, 2, 9)
              : _between(r, 11, 25),
        );
    }
  }

  // ---------------------------------------------------------------------------
  // Division
  // ---------------------------------------------------------------------------

  static MathQuestion _division(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    final (divisor, quotient) = _divisionPair(grade, difficulty, r);
    final hasRemainder = grade >= 4 && difficulty == MathDifficulty.hard;
    final remainder = hasRemainder ? _between(r, 1, divisor - 1) : 0;
    final dividend = divisor * quotient + remainder;
    final askRemainder = hasRemainder && r.nextBool();
    final correct = askRemainder ? remainder : quotient;
    final item = _items[r.nextInt(_items.length)];
    final name = _names[r.nextInt(_names.length)];

    final text = hasRemainder
        ? askRemainder
              ? 'What is the remainder when $dividend is divided by $divisor?'
              : '$dividend ÷ $divisor = ? (whole-number answer)'
        : grade == 0
        ? '$dividend ÷ $divisor = ?'
        : grade <= 2 && r.nextBool()
        ? '$name shares $dividend ${item.plural} equally among $divisor friends. '
              'How many ${item.plural} does each friend get?'
        : '$dividend ÷ $divisor = ?';

    final explanation = hasRemainder
        ? askRemainder
              ? '$divisor × $quotient = ${divisor * quotient}. '
                    '$dividend − ${divisor * quotient} = $remainder, so the remainder is $remainder.'
              : '$divisor × $quotient = ${divisor * quotient}, which is the largest '
                    'multiple of $divisor not greater than $dividend. The whole-number '
                    'answer is $quotient.'
        : '$divisor groups of $quotient make $dividend. '
              'So $dividend ÷ $divisor = $quotient.';

    return _q(
      grade: grade,
      topic: MathTopic.division,
      difficulty: difficulty,
      skill: switch (grade) {
        0 => 'share_equally',
        1 => 'divide_by_2_5_10',
        2 => 'division_intro',
        3 => 'division_facts',
        4 => 'divide_with_remainders',
        _ => 'long_division',
      },
      text: text,
      correct: '$correct',
      options: _integerOptions(
        correct,
        r,
        maxValue: max(correct + (askRemainder ? 4 : divisor + 5), 15),
      ),
      explanation: explanation,
      visual: grade <= 1 && !hasRemainder
          ? QuestionVisual(
              type: 'objects',
              data: {
                'emoji': item.emoji,
                'groups': List.filled(divisor, quotient),
                'operator': '÷',
              },
            )
          : null,
      estimatedSeconds: grade <= 2 ? 12 : 18,
    );
  }

  static (int, int) _divisionPair(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    switch (grade) {
      case 0:
        return (_between(r, 2, 3), _between(r, 1, 3));
      case 1:
        return ([2, 5, 10][r.nextInt(3)], _between(r, 1, 5));
      case 2:
        return (_between(r, 2, 5), _between(r, 2, 8));
      case 3:
        return (
          _between(r, 2, difficulty == MathDifficulty.easy ? 5 : 10),
          _between(r, 2, 10),
        );
      case 4:
        return (
          _between(r, 2, difficulty == MathDifficulty.easy ? 5 : 9),
          difficulty == MathDifficulty.easy
              ? _between(r, 2, 9)
              : _between(r, 10, 25),
        );
      default:
        return (
          _between(r, 2, 9),
          difficulty == MathDifficulty.easy
              ? _between(r, 10, 30)
              : _between(r, 30, 120),
        );
    }
  }

  // ---------------------------------------------------------------------------
  // Fractions
  // ---------------------------------------------------------------------------

  /// Denominators grow with the grade so Kindergarten and Grade 1 only see
  /// halves and fourths before thirds, fifths and eighths appear.
  static List<int> _fractionDenominators(int grade) => switch (grade) {
    0 || 1 => const [2, 4],
    2 => const [2, 3, 4, 6],
    3 => const [2, 3, 4, 5, 6, 8],
    _ => const [2, 3, 4, 5, 6, 8, 10],
  };

  static MathQuestion _fraction(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    final subtypes = switch (grade) {
      0 => const [0, 2],
      1 || 2 => const [0, 1, 2],
      _ => const [0, 1, 2, 3],
    };
    final subtype = subtypes[r.nextInt(subtypes.length)];
    final denominators = _fractionDenominators(grade);

    switch (subtype) {
      case 0:
        // Shaded fraction
        final denominator = denominators[r.nextInt(denominators.length)];
        final numerator = _between(r, 1, denominator - 1);
        final correct = '$numerator/$denominator';
        return _q(
          grade: grade,
          topic: MathTopic.fractions,
          difficulty: difficulty,
          skill: 'identify_fractions',
          text: 'What fraction of the bar is shaded?',
          correct: correct,
          options: _fractionOptions(correct, r, denominator),
          explanation:
              'The bar is split into $denominator equal parts. '
              '$numerator of those parts are shaded, so the fraction is '
              '$numerator/$denominator.',
          visual: QuestionVisual(
            type: 'fraction_bar',
            data: {'numerator': numerator, 'denominator': denominator},
          ),
          estimatedSeconds: 12,
        );
      case 1:
        // Compare fractions with the same denominator.
        final comparable = denominators.where((value) => value >= 3).toList();
        final denominator = comparable.isEmpty
            ? 4
            : comparable[r.nextInt(comparable.length)];
        var first = _between(r, 1, denominator - 1);
        var second = _between(r, 1, denominator - 1);
        if (first == second) second = first == 1 ? 2 : first - 1;
        final firstText = '$first/$denominator';
        final secondText = '$second/$denominator';
        final correct = first > second ? firstText : secondText;
        return _q(
          grade: grade,
          topic: MathTopic.fractions,
          difficulty: difficulty,
          skill: 'compare_fractions',
          text: 'Which fraction is greater?',
          correct: correct,
          options: _stringOptions(correct, [
            firstText,
            secondText,
            '$denominator/$first',
            '$denominator/$second',
          ], r),
          explanation:
              'Both fractions have the same denominator, so compare '
              'the numerators. $first vs $second means $correct is greater.',
          estimatedSeconds: 15,
        );
      case 2:
        // Fraction of a set. Early grades use small sets and a picture of the
        // equal groups so the idea stays concrete.
        final denominator = denominators[r.nextInt(denominators.length)];
        final multiplier = grade <= 1 ? _between(r, 2, 3) : _between(r, 2, 6);
        final whole = denominator * multiplier;
        final numerator = _between(r, 1, denominator - 1);
        final correct = (whole ~/ denominator) * numerator;
        return _q(
          grade: grade,
          topic: MathTopic.fractions,
          difficulty: difficulty,
          skill: 'fraction_of_set',
          text: 'What is $numerator/$denominator of $whole?',
          correct: '$correct',
          options: _integerOptions(correct, r, maxValue: max(whole, 20)),
          visual: whole <= 24
              ? QuestionVisual(
                  type: 'objects',
                  data: {
                    'emoji': '🔵',
                    'groups': List.filled(denominator, whole ~/ denominator),
                    'operator': '÷',
                  },
                )
              : null,
          explanation:
              'Divide $whole into $denominator equal groups: '
              '${whole ~/ denominator} in each group. Then take $numerator '
              'group${numerator == 1 ? '' : 's'}: '
              '${whole ~/ denominator} × $numerator = $correct.',
          estimatedSeconds: 18,
        );
      case 3:
        // Add/subtract or equivalent
        if (grade >= 5) {
          final d1 = [2, 3, 4, 5][r.nextInt(4)];
          final d2 = [2, 3, 6, 8][r.nextInt(4)];
          final lcm = _lcm(d1, d2);
          final n1 = _between(r, 1, d1 - 1);
          final n2 = _between(r, 1, d2 - 1);
          final add = r.nextBool();
          final resultNumerator = add
              ? n1 * (lcm ~/ d1) + n2 * (lcm ~/ d2)
              : n1 * (lcm ~/ d1) - n2 * (lcm ~/ d2);
          if (resultNumerator <= 0 || resultNumerator >= lcm) {
            return _fraction(grade, difficulty, Random(r.nextInt(1 << 30)));
          }
          final correct = _reduce(resultNumerator, lcm);
          final text = add ? '$n1/$d1 + $n2/$d2 = ?' : '$n1/$d1 − $n2/$d2 = ?';
          return _q(
            grade: grade,
            topic: MathTopic.fractions,
            difficulty: difficulty,
            skill: add ? 'add_unlike_fractions' : 'subtract_unlike_fractions',
            text: text,
            correct: correct,
            options: _fractionOptions(correct, r, lcm),
            explanation:
                'Use a common denominator of $lcm. '
                '$n1/$d1 = ${n1 * (lcm ~/ d1)}/$lcm and '
                '$n2/$d2 = ${n2 * (lcm ~/ d2)}/$lcm. '
                'Combining them gives $correct.',
            estimatedSeconds: 22,
          );
        }

        final denominator = denominators[r.nextInt(denominators.length)];
        final numerator = _between(r, 1, denominator - 1);
        final multiplier = _between(r, 2, 5);
        final correct = '${numerator * multiplier}/${denominator * multiplier}';
        return _q(
          grade: grade,
          topic: MathTopic.fractions,
          difficulty: difficulty,
          skill: 'equivalent_fractions',
          text: 'Which fraction is equivalent to $numerator/$denominator?',
          correct: correct,
          options: _fractionOptions(correct, r, denominator * multiplier),
          explanation:
              'Multiply the numerator and denominator by the same '
              'number ($multiplier): $numerator/$denominator = $correct.',
          visual: QuestionVisual(
            type: 'fraction_bar',
            data: {'numerator': numerator, 'denominator': denominator},
          ),
          estimatedSeconds: 18,
        );
      default:
        return _fraction(grade, difficulty, Random(r.nextInt(1 << 30)));
    }
  }

  // ---------------------------------------------------------------------------
  // Geometry
  // ---------------------------------------------------------------------------

  static MathQuestion _geometry(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    if (grade <= 1) {
      const shapes = <({String name, int sides, String svg})>[
        (name: 'triangle', sides: 3, svg: 'triangle'),
        (name: 'square', sides: 4, svg: 'square'),
        (name: 'rectangle', sides: 4, svg: 'rectangle'),
        (name: 'circle', sides: 0, svg: 'circle'),
        (name: 'pentagon', sides: 5, svg: 'pentagon'),
        (name: 'hexagon', sides: 6, svg: 'hexagon'),
      ];
      final shape = shapes[r.nextInt(shapes.length)];
      final askSides = shape.sides > 0 && r.nextBool();
      return _q(
        grade: grade,
        topic: MathTopic.geometry,
        difficulty: difficulty,
        skill: askSides ? 'count_sides' : 'name_shapes',
        text: askSides
            ? 'How many sides does this shape have?'
            : 'What is the name of this shape?',
        correct: askSides ? '${shape.sides}' : shape.name,
        options: askSides
            ? _integerOptions(shape.sides, r, maxValue: 10)
            : _stringOptions(shape.name, [
                'triangle',
                'square',
                'rectangle',
                'circle',
                'pentagon',
                'hexagon',
              ], r),
        explanation: askSides
            ? 'A ${shape.name} has ${shape.sides} sides.'
            : 'This shape is a ${shape.name}.',
        visual: QuestionVisual(type: 'shape', data: {'shape': shape.svg}),
        estimatedSeconds: 10,
      );
    }

    if (grade >= 5) {
      if (r.nextBool()) {
        final length = _between(r, 2, 6);
        final width = _between(r, 2, 5);
        final height = _between(r, 2, 4);
        final volume = length * width * height;
        return _q(
          grade: grade,
          topic: MathTopic.geometry,
          difficulty: difficulty,
          skill: 'volume_rectangular_prism',
          text: 'What is the volume of this rectangular prism?',
          correct: '$volume cubic units',
          options: _stringOptions('$volume cubic units', [
            '${length + width + height} cubic units',
            '${2 * (length * width + length * height + width * height)} cubic units',
            '${length * width} cubic units',
            '${volume + length} cubic units',
          ], r),
          explanation:
              'Volume = length × width × height = '
              '$length × $width × $height = $volume cubic units.',
          visual: QuestionVisual(
            type: 'volume',
            data: {'length': length, 'width': width, 'height': height},
          ),
          estimatedSeconds: 20,
        );
      }
      final x = _between(r, 1, 6);
      final y = _between(r, 1, 6);
      return _q(
        grade: grade,
        topic: MathTopic.geometry,
        difficulty: difficulty,
        skill: 'coordinate_plane',
        text: 'Which ordered pair names the marked point?',
        correct: '($x, $y)',
        options: _stringOptions('($x, $y)', [
          '($y, $x)',
          '(${x + 1}, $y)',
          '($x, ${y + 1})',
          '(${x + y}, 0)',
        ], r),
        explanation:
            'Start at 0. Move $x right along the x-axis, then $y up '
            'along the y-axis. The point is ($x, $y).',
        visual: QuestionVisual(type: 'coordinate', data: {'x': x, 'y': y}),
        estimatedSeconds: 18,
      );
    }

    if (grade == 4 && r.nextBool()) {
      final angle = [30, 45, 60, 90, 120, 135, 150][r.nextInt(7)];
      final correct = angle == 90
          ? 'right angle'
          : angle < 90
          ? 'acute angle'
          : 'obtuse angle';
      return _q(
        grade: grade,
        topic: MathTopic.geometry,
        difficulty: difficulty,
        skill: 'classify_angles',
        text: 'What kind of angle is shown?',
        correct: correct,
        options: _stringOptions(correct, [
          'acute angle',
          'right angle',
          'obtuse angle',
          'straight angle',
        ], r),
        explanation: angle == 90
            ? 'A right angle measures exactly 90°.'
            : angle < 90
            ? 'An acute angle is smaller than a right angle (less than 90°).'
            : 'An obtuse angle is larger than a right angle but less than 180°.',
        visual: QuestionVisual(type: 'angle', data: {'degrees': angle}),
        estimatedSeconds: 14,
      );
    }

    final width = _between(r, 3, 12);
    final height = _between(r, 2, 9);
    final askArea = grade >= 3 && r.nextBool();
    final answer = askArea ? width * height : 2 * (width + height);
    return _q(
      grade: grade,
      topic: MathTopic.geometry,
      difficulty: difficulty,
      skill: askArea ? 'area_rectangles' : 'perimeter_rectangles',
      text: askArea
          ? 'What is the area of this rectangle?'
          : 'What is the perimeter of this rectangle?',
      correct: askArea ? '$answer square units' : '$answer units',
      options:
          _stringOptions(askArea ? '$answer square units' : '$answer units', [
            askArea
                ? '${2 * (width + height)} square units'
                : '${width * height} units',
            '${answer + width} ${askArea ? 'square units' : 'units'}',
            '${answer - height} ${askArea ? 'square units' : 'units'}',
            '${width + height} ${askArea ? 'square units' : 'units'}',
          ], r),
      explanation: askArea
          ? 'Area of a rectangle = length × width = $width × $height = '
                '$answer square units.'
          : 'Perimeter = 2 × (length + width) = 2 × ($width + $height) = '
                '$answer units.',
      visual: QuestionVisual(
        type: 'shape',
        data: {'shape': 'rectangle', 'width': width, 'height': height},
      ),
      estimatedSeconds: 16,
    );
  }

  // ---------------------------------------------------------------------------
  // Measurement
  // ---------------------------------------------------------------------------

  static MathQuestion _measurement(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    if (grade <= 1) {
      final subtype = r.nextInt(2);
      if (subtype == 0) {
        final longer = r.nextBool();
        final shortLength = _between(r, 2, 5);
        final longLength = shortLength + _between(r, 2, 5);
        final correct = longer
            ? (longLength >= shortLength ? 'the blue rope' : 'the red rope')
            : (shortLength < longLength ? 'the blue rope' : 'the red rope');
        return _q(
          grade: grade,
          topic: MathTopic.measurement,
          difficulty: difficulty,
          skill: 'compare_lengths',
          text: longer ? 'Which rope is longer?' : 'Which rope is shorter?',
          correct: correct,
          options: _stringOptions(correct, [
            'the blue rope',
            'the red rope',
            'they are the same',
            'cannot tell',
          ], r),
          explanation:
              'Compare the lengths directly. The blue rope is '
              '$longLength units and the red rope is $shortLength units, so '
              'the answer is $correct.',
          visual: QuestionVisual(
            type: 'ruler',
            data: {'blue': longLength, 'red': shortLength, 'unit': 'units'},
          ),
          estimatedSeconds: 10,
        );
      }

      final hour = _between(r, 1, 12);
      final minute = r.nextBool() ? 0 : 30;
      final correct = '$hour:${minute == 0 ? '00' : '30'}';
      return _q(
        grade: grade,
        topic: MathTopic.measurement,
        difficulty: difficulty,
        skill: 'tell_time',
        text: 'What time does the clock show?',
        correct: correct,
        options: _stringOptions(correct, [
          '$hour:${minute == 0 ? '30' : '00'}',
          '${hour == 12 ? 1 : hour + 1}:${minute == 0 ? '00' : '30'}',
          '${hour == 1 ? 12 : hour - 1}:${minute == 0 ? '00' : '30'}',
          '$hour:15',
        ], r),
        explanation:
            'The short hand points to $hour and the long hand points '
            'to ${minute == 0 ? '12, which means o’clock' : '6, which means half past'}. '
            'The time is $correct.',
        visual: QuestionVisual(
          type: 'clock',
          data: {'hour': hour, 'minute': minute},
        ),
        estimatedSeconds: 12,
      );
    }

    if (grade >= 4) {
      final subtype = r.nextInt(4);
      switch (subtype) {
        case 0:
          final meters = _between(r, 2, 9);
          final correct = meters * 100;
          return _q(
            grade: grade,
            topic: MathTopic.measurement,
            difficulty: difficulty,
            skill: 'metric_length_conversion',
            text: 'How many centimeters are in $meters meters?',
            correct: '$correct',
            options: _integerOptions(correct, r, maxValue: correct + 200),
            explanation:
                '1 meter = 100 centimeters. '
                '$meters × 100 = $correct centimeters.',
            estimatedSeconds: 13,
          );
        case 1:
          final kilograms = _between(r, 2, 8);
          final correct = kilograms * 1000;
          return _q(
            grade: grade,
            topic: MathTopic.measurement,
            difficulty: difficulty,
            skill: 'metric_mass_conversion',
            text: 'How many grams are in $kilograms kilograms?',
            correct: '$correct',
            options: _integerOptions(correct, r, maxValue: correct + 2000),
            explanation:
                '1 kilogram = 1,000 grams. '
                '$kilograms × 1,000 = $correct grams.',
            estimatedSeconds: 13,
          );
        case 2:
          final liters = _between(r, 2, 7);
          final correct = liters * 1000;
          return _q(
            grade: grade,
            topic: MathTopic.measurement,
            difficulty: difficulty,
            skill: 'metric_volume_conversion',
            text: 'How many milliliters are in $liters liters?',
            correct: '$correct',
            options: _integerOptions(correct, r, maxValue: correct + 1500),
            explanation:
                '1 liter = 1,000 milliliters. '
                '$liters × 1,000 = $correct milliliters.',
            estimatedSeconds: 13,
          );
        default:
          final startHour = _between(r, 1, 9);
          final startMinute = [0, 15, 30, 45][r.nextInt(4)];
          final elapsed = [15, 30, 45, 60][r.nextInt(4)];
          final total = startHour * 60 + startMinute + elapsed;
          final endHour = (total ~/ 60) % 12 == 0 ? 12 : (total ~/ 60) % 12;
          final endMinute = total % 60;
          final correct = '$endHour:${endMinute.toString().padLeft(2, '0')}';
          return _q(
            grade: grade,
            topic: MathTopic.measurement,
            difficulty: difficulty,
            skill: 'elapsed_time',
            text:
                'A movie starts at $startHour:${startMinute.toString().padLeft(2, '0')} '
                'and lasts $elapsed minutes. What time does it end?',
            correct: correct,
            options: _stringOptions(correct, [
              '$startHour:${((startMinute + elapsed) % 60).toString().padLeft(2, '0')}',
              '${endHour == 12 ? 1 : endHour + 1}:${endMinute.toString().padLeft(2, '0')}',
              '$endHour:${((endMinute + 15) % 60).toString().padLeft(2, '0')}',
              '$startHour:${startMinute.toString().padLeft(2, '0')}',
            ], r),
            explanation:
                'Add $elapsed minutes to $startHour:'
                '${startMinute.toString().padLeft(2, '0')}. The movie ends at '
                '$correct.',
            estimatedSeconds: 20,
          );
      }
    }

    final subtype = r.nextInt(3);
    switch (subtype) {
      case 0:
        final price = _between(r, 2, 9);
        final cents = [25, 50, 75][r.nextInt(3)];
        final correct = price * 100 + cents;
        return _q(
          grade: grade,
          topic: MathTopic.measurement,
          difficulty: difficulty,
          skill: 'money',
          text:
              'How many cents is \$$price.${cents.toString().padLeft(2, '0')}?',
          correct: '$correct',
          options: _integerOptions(correct, r, maxValue: correct + 150),
          explanation:
              'Each dollar is 100 cents. '
              '$price × 100 + $cents = $correct cents.',
          estimatedSeconds: 14,
        );
      case 1:
        final meters = _between(r, 2, 9);
        final correct = meters * 100;
        return _q(
          grade: grade,
          topic: MathTopic.measurement,
          difficulty: difficulty,
          skill: 'metric_length_conversion',
          text: 'How many centimeters are in $meters meters?',
          correct: '$correct',
          options: _integerOptions(correct, r, maxValue: correct + 200),
          explanation:
              '1 meter = 100 centimeters. '
              '$meters × 100 = $correct centimeters.',
          estimatedSeconds: 13,
        );
      default:
        final minutes = _between(r, 2, 6) * 10;
        final correct = '${minutes ~/ 60} h ${minutes % 60} min';
        return _q(
          grade: grade,
          topic: MathTopic.measurement,
          difficulty: difficulty,
          skill: 'time_conversion',
          text: 'How many hours and minutes are in $minutes minutes?',
          correct: correct,
          options: _stringOptions(correct, [
            '${minutes ~/ 60 + 1} h ${minutes % 60} min',
            '${minutes ~/ 60} h ${(minutes + 10) % 60} min',
            '${minutes ~/ 60} h',
            '$minutes h 0 min',
          ], r),
          explanation:
              'There are 60 minutes in an hour. '
              '$minutes minutes is $correct.',
          estimatedSeconds: 15,
        );
    }
  }

  // ---------------------------------------------------------------------------
  // Place value
  // ---------------------------------------------------------------------------

  static MathQuestion _placeValue(
    int grade,
    MathDifficulty difficulty,
    Random r,
  ) {
    if (grade == 0) {
      final tens = _between(r, 1, 5);
      final ones = _between(r, 1, 9);
      final number = tens * 10 + ones;
      final askTens = r.nextBool();
      final correct = askTens ? tens : ones;
      return _q(
        grade: grade,
        topic: MathTopic.placeValue,
        difficulty: difficulty,
        skill: 'base_ten_blocks',
        text: askTens
            ? 'How many tens are in $number?'
            : 'How many ones are in $number?',
        correct: '$correct',
        options: _integerOptions(correct, r, maxValue: 20),
        explanation: askTens
            ? 'The blocks show $tens tens and $ones ones, so there are '
                  '$tens tens.'
            : 'The blocks show $tens tens and $ones ones, so there are '
                  '$ones ones.',
        visual: QuestionVisual(
          type: 'base_ten',
          data: {'tens': tens, 'ones': ones},
        ),
        estimatedSeconds: 14,
      );
    }

    if (grade == 1) {
      final tens = _between(r, 1, 5);
      final ones = _between(r, 1, 9);
      final number = tens * 10 + ones;
      final askValue = r.nextBool();
      return _q(
        grade: grade,
        topic: MathTopic.placeValue,
        difficulty: difficulty,
        skill: askValue ? 'digit_value' : 'base_ten_blocks',
        text: askValue
            ? 'What is the $tens in $number worth?'
            : 'How many blocks are shown?',
        correct: askValue ? '${tens * 10}' : '$number',
        options: _integerOptions(
          askValue ? tens * 10 : number,
          r,
          maxValue: 100,
        ),
        explanation: askValue
            ? 'The digit $tens is in the tens place, so it is worth '
                  '${tens * 10}. That is $tens groups of ten.'
            : '$tens tens and $ones ones make $number.',
        visual: QuestionVisual(
          type: 'base_ten',
          data: {'tens': tens, 'ones': ones},
        ),
        estimatedSeconds: 12,
      );
    }

    if (grade == 5) {
      final subtype = r.nextInt(3);
      final whole = _between(r, 1, 9);
      final tenths = _between(r, 1, 9);
      final hundredths = _between(r, 1, 9);
      final number = '$whole.$tenths$hundredths';
      if (subtype == 0) {
        final correct = '${tenths / 10}';
        return _q(
          grade: grade,
          topic: MathTopic.placeValue,
          difficulty: difficulty,
          skill: 'decimal_digit_value',
          text: 'In $number, what is the value of the digit $tenths?',
          correct: correct,
          options: _stringOptions(correct, [
            '${tenths.toDouble()}',
            '${hundredths / 100}',
            '$whole',
            '${tenths / 100}',
          ], r),
          explanation:
              'The digit $tenths is in the tenths place, so its value '
              'is $correct.',
          estimatedSeconds: 15,
        );
      }
      if (subtype == 1) {
        final correct = '$whole.$tenths$hundredths';
        return _q(
          grade: grade,
          topic: MathTopic.placeValue,
          difficulty: difficulty,
          skill: 'decimal_expanded_form',
          text:
              '$whole + ${_decimal(tenths / 10)} + '
              '${_decimal(hundredths / 100)} = ?',
          correct: correct,
          options: _stringOptions(correct, [
            '$whole.$tenths',
            '$tenths.$whole$hundredths',
            '${whole + tenths}.$hundredths',
            '$whole.0$tenths$hundredths',
          ], r),
          explanation:
              'Add the whole number and each decimal place: '
              '$whole + ${_decimal(tenths / 10)} + '
              '${_decimal(hundredths / 100)} = $correct.',
          estimatedSeconds: 18,
        );
      }
      final power = _between(r, 2, 4);
      final correct = pow(10, power).toInt();
      return _q(
        grade: grade,
        topic: MathTopic.placeValue,
        difficulty: difficulty,
        skill: 'powers_of_ten',
        text: '${List.filled(power, '10').join(' × ')} = ?',
        correct: '$correct',
        options: _integerOptions(correct, r, maxValue: correct * 10),
        explanation:
            'Multiplying ten by itself $power times makes '
            '$correct (1 followed by $power zeros).',
        estimatedSeconds: 12,
      );
    }

    final subtype = r.nextInt(3);
    if (subtype == 0) {
      final number = _between(r, 100, 999);
      final digits = number.toString().split('');
      final index = r.nextInt(3);
      final digit = digits[index];
      final place = [100, 10, 1][index];
      final correct = '${int.parse(digit) * place}';
      return _q(
        grade: grade,
        topic: MathTopic.placeValue,
        difficulty: difficulty,
        skill: 'digit_value',
        text: 'In $number, what is the value of the digit $digit?',
        correct: correct,
        options: _integerOptions(
          int.parse(correct),
          r,
          maxValue: max(number, 1000),
        ),
        explanation:
            'The digit $digit is in the '
            '${place == 100
                ? 'hundreds'
                : place == 10
                ? 'tens'
                : 'ones'} '
            'place, so its value is $correct.',
        estimatedSeconds: 14,
      );
    }
    if (subtype == 1) {
      final number = _between(r, 100, 999);
      final nearest = r.nextBool() ? 10 : 100;
      final correct = ((number / nearest).round() * nearest).toInt();
      return _q(
        grade: grade,
        topic: MathTopic.placeValue,
        difficulty: difficulty,
        skill: 'rounding',
        text: 'Round $number to the nearest $nearest.',
        correct: '$correct',
        options: _integerOptions(correct, r, maxValue: correct + 100),
        explanation:
            'Look at the digit to the right of the $nearest place. '
            '$number rounds to $correct.',
        estimatedSeconds: 15,
      );
    }
    final hundreds = _between(r, 1, 9);
    final tens = _between(r, 0, 9);
    final ones = _between(r, 0, 9);
    final number = hundreds * 100 + tens * 10 + ones;
    return _q(
      grade: grade,
      topic: MathTopic.placeValue,
      difficulty: difficulty,
      skill: 'expanded_form',
      text: '$hundreds hundreds + $tens tens + $ones ones = ?',
      correct: '$number',
      options: _integerOptions(number, r, maxValue: number + 200),
      explanation:
          '$hundreds hundreds = ${hundreds * 100}, '
          '$tens tens = ${tens * 10}, and $ones ones = $ones. '
          'Together they make $number.',
      visual: QuestionVisual(
        type: 'base_ten',
        data: {'hundreds': hundreds, 'tens': tens, 'ones': ones},
      ),
      estimatedSeconds: 15,
    );
  }

  // ---------------------------------------------------------------------------
  // Mixed challenge
  // ---------------------------------------------------------------------------

  static MathQuestion _mixed(int grade, MathDifficulty difficulty, Random r) {
    if (grade == 0) {
      final subtype = r.nextInt(3);
      if (subtype == 0) {
        final count = _between(r, 3, 9);
        final emoji = _items[r.nextInt(_items.length)].emoji;
        return _q(
          grade: grade,
          topic: MathTopic.mixed,
          difficulty: difficulty,
          skill: 'counting',
          text: 'How many objects are shown?',
          correct: '$count',
          options: _integerOptions(count, r, maxValue: 12),
          explanation: 'Count each object once: there are $count.',
          visual: QuestionVisual(
            type: 'objects',
            data: {
              'emoji': emoji,
              'groups': [count],
              'operator': '',
            },
          ),
          estimatedSeconds: 8,
        );
      }
      if (subtype == 1) {
        final start = _between(r, 1, 5);
        final step = r.nextBool() ? 1 : 2;
        final correct = start + step * 4;
        return _q(
          grade: grade,
          topic: MathTopic.mixed,
          difficulty: difficulty,
          skill: 'number_patterns',
          text:
              'What number comes next? '
              '${List.generate(4, (i) => start + step * i).join(', ')}, ?',
          correct: '$correct',
          options: _integerOptions(correct, r, maxValue: correct + 5),
          explanation:
              'The pattern counts by $step. After '
              '${start + step * 3}, the next number is $correct.',
          visual: QuestionVisual(
            type: 'number_line',
            data: {
              'min': start - 1,
              'max': correct + 1,
              'start': start,
              'jump': step,
            },
          ),
          estimatedSeconds: 12,
        );
      }
      final left = _between(r, 1, 5);
      final right = _between(r, 1, 5);
      final correct = left > right
          ? '$left is greater'
          : left < right
          ? '$right is greater'
          : 'they are equal';
      return _q(
        grade: grade,
        topic: MathTopic.mixed,
        difficulty: difficulty,
        skill: 'compare_quantities',
        text: 'Which group has more?',
        correct: correct,
        options: _stringOptions(correct, [
          '$left is greater',
          '$right is greater',
          'they are equal',
          'cannot tell',
        ], r),
        explanation:
            'Compare the two groups. $correct, because '
            '$left ${left > right
                ? '>'
                : left < right
                ? '<'
                : '='} $right.',
        visual: QuestionVisual(
          type: 'objects',
          data: {
            'emoji': _items[r.nextInt(_items.length)].emoji,
            'groups': [left, right],
            'operator': 'vs',
          },
        ),
        estimatedSeconds: 10,
      );
    }

    if (grade <= 2) {
      final subtype = r.nextInt(3);
      if (subtype == 0) {
        final total = _between(r, 5, grade == 1 ? 20 : 50);
        final part = _between(r, 1, total - 1);
        final correct = total - part;
        return _q(
          grade: grade,
          topic: MathTopic.mixed,
          difficulty: difficulty,
          skill: 'number_bonds',
          text: '$part + ? = $total',
          correct: '$correct',
          options: _integerOptions(correct, r, maxValue: total),
          explanation:
              'A number bond shows two parts that make a whole. '
              '$total − $part = $correct.',
          visual: QuestionVisual(
            type: 'bar_model',
            data: {
              'parts': [part],
              'total': total,
            },
          ),
          estimatedSeconds: 13,
        );
      }
      if (subtype == 1) {
        final step = [2, 5, 10][r.nextInt(3)];
        final start = step * _between(r, 1, 4);
        final correct = start + step * 5;
        return _q(
          grade: grade,
          topic: MathTopic.mixed,
          difficulty: difficulty,
          skill: 'skip_counting',
          text:
              'Keep skip counting by $step: '
              '${List.generate(5, (i) => start + step * i).join(', ')}, ?',
          correct: '$correct',
          options: _integerOptions(correct, r, maxValue: correct + 20),
          explanation:
              'The pattern adds $step each time. '
              '${start + step * 4} + $step = $correct.',
          estimatedSeconds: 13,
        );
      }
      final pencils = _between(r, 2, 9);
      final packs = _between(r, 2, 5);
      final extra = _between(r, 1, 6);
      final correct = pencils * packs + extra;
      return _q(
        grade: grade,
        topic: MathTopic.mixed,
        difficulty: difficulty,
        skill: 'multi_step_word_problem',
        text:
            'A shop has $packs packs of pencils with $pencils pencils in '
            'each pack, plus $extra single pencils. How many pencils are there?',
        correct: '$correct',
        options: _integerOptions(correct, r, maxValue: correct + 20),
        explanation:
            'First find the packs: $pencils × $packs = '
            '${pencils * packs}. Then add the singles: '
            '${pencils * packs} + $extra = $correct.',
        estimatedSeconds: 20,
      );
    }

    if (grade >= 5) {
      final subtype = r.nextInt(3);
      if (subtype == 0) {
        final a = _between(r, 2, 9);
        final b = _between(r, 2, 9);
        final c = _between(r, 2, 9);
        final addFirst = r.nextBool();
        final correct = addFirst ? a + b * c : (a + b) * c;
        return _q(
          grade: grade,
          topic: MathTopic.mixed,
          difficulty: difficulty,
          skill: 'order_of_operations',
          text: addFirst ? '$a + $b × $c = ?' : '($a + $b) × $c = ?',
          correct: '$correct',
          options: _integerOptions(correct, r, maxValue: correct + 30),
          explanation: addFirst
              ? 'Multiplication comes before addition: '
                    '$b × $c = ${b * c}, then $a + ${b * c} = $correct.'
              : 'Solve the parentheses first: $a + $b = ${a + b}, '
                    'then ${a + b} × $c = $correct.',
          estimatedSeconds: 20,
        );
      }
      if (subtype == 1) {
        final x = _between(r, 2, 12);
        final add = _between(r, 2, 20);
        final total = x + add;
        return _q(
          grade: grade,
          topic: MathTopic.mixed,
          difficulty: difficulty,
          skill: 'simple_equations',
          text: 'Solve for x: x + $add = $total',
          correct: '$x',
          options: _integerOptions(x, r, maxValue: total),
          explanation:
              'Subtract $add from both sides: '
              'x = $total − $add = $x.',
          estimatedSeconds: 16,
        );
      }
      final price = _between(r, 3, 12);
      final quantity = _between(r, 3, 9);
      final budget = price * quantity + _between(r, 5, 20);
      final correct = budget - price * quantity;
      return _q(
        grade: grade,
        topic: MathTopic.mixed,
        difficulty: difficulty,
        skill: 'multi_step_word_problem',
        text:
            'A team buys $quantity notebooks for \$$price each and has '
            '\$$budget in total. How much money is left?',
        correct: '\$$correct',
        options: _stringOptions('\$$correct', [
          '\$${budget + price * quantity}',
          '\$${price * quantity}',
          '\$${correct + price}',
          '\$${budget - price}',
        ], r),
        explanation:
            'The notebooks cost $quantity × \$$price = '
            '\$${price * quantity}. Subtract that from the budget: '
            '\$$budget − \$${price * quantity} = \$$correct.',
        estimatedSeconds: 22,
      );
    }

    final subtype = r.nextInt(3);
    if (subtype == 0) {
      final a = _between(r, 3, 12);
      final b = _between(r, 2, 9);
      final c = _between(r, 2, 9);
      final correct = a + b * c;
      return _q(
        grade: grade,
        topic: MathTopic.mixed,
        difficulty: difficulty,
        skill: 'order_of_operations',
        text: '$a + $b × $c = ?',
        correct: '$correct',
        options: _integerOptions(correct, r, maxValue: correct + 30),
        explanation:
            'Do multiplication first: $b × $c = ${b * c}. '
            'Then add: $a + ${b * c} = $correct.',
        estimatedSeconds: 18,
      );
    }
    if (subtype == 1) {
      final number = _between(r, 20, 90);
      final factor = [2, 3, 4, 5, 6, 7, 8, 9][r.nextInt(8)];
      final isFactor = number % factor == 0;
      final correct = isFactor ? 'yes' : 'no';
      return _q(
        grade: grade,
        topic: MathTopic.mixed,
        difficulty: difficulty,
        skill: 'factors_and_multiples',
        text: 'Is $factor a factor of $number?',
        correct: correct,
        options: _stringOptions(correct, [
          'yes',
          'no',
          'only if even',
          'cannot tell',
        ], r),
        explanation: isFactor
            ? '$number ÷ $factor = ${number ~/ factor} with no remainder, '
                  'so $factor is a factor of $number.'
            : '$number ÷ $factor is not a whole number, so $factor is not a '
                  'factor of $number.',
        estimatedSeconds: 16,
      );
    }
    final packets = _between(r, 3, 8);
    final perPacket = _between(r, 4, 12);
    final eaten = _between(r, 2, 10);
    final correct = packets * perPacket - eaten;
    return _q(
      grade: grade,
      topic: MathTopic.mixed,
      difficulty: difficulty,
      skill: 'multi_step_word_problem',
      text:
          'A class has $packets boxes with $perPacket markers in each box. '
          'They give away $eaten markers. How many markers remain?',
      correct: '$correct',
      options: _integerOptions(correct, r, maxValue: correct + 30),
      explanation:
          'First multiply: $packets × $perPacket = '
          '${packets * perPacket}. Then subtract: '
          '${packets * perPacket} − $eaten = $correct.',
      estimatedSeconds: 22,
    );
  }

  // ---------------------------------------------------------------------------
  // Helpers and validation
  // ---------------------------------------------------------------------------

  static MathQuestion _q({
    required int grade,
    required MathTopic topic,
    required MathDifficulty difficulty,
    required String skill,
    required String text,
    required String correct,
    required List<String> options,
    required String explanation,
    QuestionVisual? visual,
    int estimatedSeconds = 15,
  }) {
    final unique = <String>{};
    final cleanedOptions = <String>[];
    for (final option in options) {
      final trimmed = option.trim();
      if (unique.add(trimmed)) cleanedOptions.add(trimmed);
    }
    while (cleanedOptions.length < 4) {
      cleanedOptions.add('${cleanedOptions.length + 1}?');
    }
    final shuffled = [...cleanedOptions]
      ..shuffle(Random(correct.hashCode + grade));
    if (!shuffled.contains(correct)) {
      shuffled[0] = correct;
    }

    return MathQuestion(
      grade: grade,
      topic: topic,
      difficulty: difficulty,
      skill: skill,
      text: text,
      correctAnswer: correct,
      options: shuffled,
      explanation: explanation,
      answerType: AnswerType.choice,
      estimatedSeconds: estimatedSeconds,
      curriculumTags: ['grade_$grade', topic.dbValue, difficulty.dbValue],
      hint: _hintFor(topic),
      visual: visual,
    );
  }

  static void _validate(MathQuestion question) {
    if (question.text.trim().isEmpty) {
      throw StateError('Question text cannot be empty');
    }
    if (question.explanation.trim().isEmpty) {
      throw StateError('Question explanation cannot be empty');
    }
    if (question.options.length != 4) {
      throw StateError(
        'Question must have exactly 4 options, got ${question.options.length}: '
        '${question.text}',
      );
    }
    if (question.options.toSet().length != 4) {
      throw StateError('Question options must be distinct: ${question.text}');
    }
    if (!question.options.contains(question.correctAnswer)) {
      throw StateError(
        'Correct answer "${question.correctAnswer}" missing from options for '
        '${question.text}',
      );
    }
    if (question.grade < 0 || question.grade > 5) {
      throw StateError('Invalid grade ${question.grade}');
    }
    if (question.estimatedSeconds <= 0) {
      throw StateError('Estimated time must be positive');
    }
  }

  static String _additionExplanation(int a, int b, int sum) {
    if (a + b <= 20) {
      return 'Start at $a and count on $b more. '
          'You land on $sum, so $a + $b = $sum.';
    }
    return 'Line up $a and $b. Add the ones, then the tens and hundreds. '
        '$a + $b = $sum.';
  }

  static String _subtractionExplanation(int a, int b, int difference) {
    if (a <= 20) {
      return 'Start at $a and count back $b. '
          'You land on $difference, so $a − $b = $difference.';
    }
    return 'Line up $a and $b. Subtract the ones, then the tens and hundreds. '
        '$a − $b = $difference.';
  }

  static String _multiplicationExplanation(int a, int b, int product) {
    if (a <= 12 && b <= 12) {
      final repeated = List.filled(a, '$b').join(' + ');
      return '$a groups of $b make $product. '
          'You can also add $repeated = $product.';
    }
    final tensA = a ~/ 10 * 10;
    final onesA = a % 10;
    return 'Break $a into $tensA + $onesA. '
        '$tensA × $b = ${tensA * b} and $onesA × $b = ${onesA * b}. '
        'Add them: ${tensA * b} + ${onesA * b} = $product.';
  }

  static List<String> _integerOptions(
    int correct,
    Random random, {
    required int maxValue,
  }) {
    final values = <int>{correct};
    final candidates = <int>[
      correct + 1,
      correct - 1,
      correct + 2,
      correct - 2,
      correct + 10,
      correct - 10,
      correct + 3,
      correct - 3,
      correct ~/ 10,
      correct * 2,
    ]..shuffle(random);

    for (final candidate in candidates) {
      if (values.length >= 4) break;
      if (candidate < 0) continue;
      if (candidate > maxValue + 1000) continue;
      values.add(candidate);
    }

    var attempts = 0;
    while (values.length < 4 && attempts < 200) {
      attempts++;
      final candidate = random.nextInt(max(12, maxValue + 1));
      values.add(candidate);
    }

    final list = values.map((value) => '$value').toList()..shuffle(random);
    return list;
  }

  static List<String> _stringOptions(
    String correct,
    List<String> candidates,
    Random random,
  ) {
    final values = <String>{correct};
    for (final candidate in candidates) {
      if (values.length >= 4) break;
      if (candidate.trim().isEmpty) continue;
      values.add(candidate.trim());
    }
    var counter = 1;
    while (values.length < 4) {
      values.add('option ${counter++}');
    }
    return values.toList()..shuffle(random);
  }

  static List<String> _fractionOptions(
    String correct,
    Random random,
    int denominator,
  ) {
    final candidates = <String>[];
    final parts = correct.split('/');
    if (parts.length == 2) {
      final n = int.tryParse(parts[0]) ?? 1;
      final d = int.tryParse(parts[1]) ?? denominator;
      candidates.addAll([
        '$n/${d + 1}',
        '${n + 1}/$d',
        '${n + 1}/${d + 1}',
        '${max(1, n - 1)}/$d',
        '$d/$n',
        '${n * 2}/${d * 2}',
      ]);
    }
    return _stringOptions(correct, candidates, random);
  }

  static int _between(Random random, int min, int max) {
    if (max < min) return min;
    return min + random.nextInt(max - min + 1);
  }

  static String _decimal(num value) {
    final text = value.toStringAsFixed(2);
    return text
        .replaceFirst(RegExp(r'0+$'), '')
        .replaceFirst(RegExp(r'\.$'), '');
  }

  static int _gcd(int a, int b) => b == 0 ? a : _gcd(b, a % b);
  static int _lcm(int a, int b) => (a * b) ~/ _gcd(a, b);

  static String _reduce(int numerator, int denominator) {
    final gcd = _gcd(numerator, denominator);
    return '${numerator ~/ gcd}/${denominator ~/ gcd}';
  }

  static String _hintFor(MathTopic topic) {
    return switch (topic) {
      MathTopic.addition => 'Try counting on from the larger number.',
      MathTopic.subtraction =>
        'Try counting back, or think of the missing part.',
      MathTopic.multiplication => 'Think of equal groups or an array.',
      MathTopic.division => 'Think of sharing into equal groups.',
      MathTopic.fractions =>
        'Remember: the denominator tells how many equal parts.',
      MathTopic.geometry =>
        'Look at the sides, corners, or units in the picture.',
      MathTopic.measurement =>
        'Check the unit and use the conversion you know.',
      MathTopic.placeValue => 'Think about ones, tens, and hundreds places.',
      MathTopic.mixed => 'Break the problem into smaller steps.',
    };
  }
}
